const out = [];
for (const item of $input.all()) {
  const row = item.json;
  let abs = row.abstraction_json;
  if (typeof abs === 'string') { try { abs = JSON.parse(abs); } catch (e) { abs = {}; } }
  abs = abs || {};
  const parts = [abs.pattern, abs.category, abs.transferable_thesis, abs.enabling_shift].filter(Boolean);
  out.push({ json: { idea_id: row.id, abstraction_json: abs, query_text: parts.join('. ') } });
}
return out;

const out = [];
const items = $input.all();
const built = $('Build Query Text').all();
for (let i = 0; i < items.length; i++) {
  const emb = items[i].json.data[0].embedding;
  out.push({ json: {
    idea_id: built[i].json.idea_id,
    abstraction_json: built[i].json.abstraction_json,
    query_text: built[i].json.query_text,
    query_vector: '[' + emb.join(',') + ']'
  } });
}
return out;

const items = $input.all();
const prior = $('Format Vector Literal').first().json;
const abs = prior.abstraction_json || {};

const evidenceRefs = [];
let evidenceBlock = '';
let snapshotId = null;

const titleCounts = {};
items.forEach((it) => {
  const c = it.json;
  if (!snapshotId && c.kb_snapshot_id) snapshotId = c.kb_snapshot_id;

  const baseLabel = (c.doc_title && String(c.doc_title).trim()) ? String(c.doc_title).trim() : (c.doc_type || 'KB Source');
  titleCounts[baseLabel] = (titleCounts[baseLabel] || 0) + 1;
  const ref = titleCounts[baseLabel] > 1 ? (baseLabel + ' \u00a7' + titleCounts[baseLabel]) : baseLabel;

  evidenceRefs.push({ ref, doc_type: c.doc_type, doc_title: c.doc_title, chunk_index: c.chunk_index, distance: c.distance });
  evidenceBlock += '[' + ref + ']\n' + (c.chunk_text || '') + '\n\n';
});

const systemPrompt = [
  'You are a national policy analyst. You ground a startup idea against national-level evidence and decide whether it survives a knockout filter.',
  'Base every factual claim ONLY on the provided KB evidence chunks below, each labelled with its source name in brackets. Do not invent national facts. If evidence is insufficient, say so explicitly.',
  'Pay particular attention to any evidence chunk describing an EXISTING GOVERNMENT initiative, authority, or platform. If the idea substantially duplicates what such a chunk describes as already live, that is a distinct and important knockout condition from ordinary private-sector competition — see condition 4 below.',
  'IMPORTANT — long-horizon frontier/deep-tech ideas (e.g. fusion or advanced nuclear energy, quantum computing hardware, advanced space propulsion, novel materials science, foundational biotech): these should NOT be evaluated as if they need a near-term paying commercial customer. A sovereign wealth fund, strategic-investment vehicle, or government body with a plausible mandate to fund long-horizon strategic technology counts as a valid anchor buyer for these categories — do not apply condition 3 to a frontier idea merely because no near-term commercial customer is named. Reserve this leniency for ideas whose core technology genuinely requires a multi-year, capital-intensive build; do not extend it to ordinary software or applied-technology ventures just because they are ambitious.',
  '',
  'Return ONLY a JSON object with EXACTLY this shape:',
  '{',
  '  "national_context": {',
  '    "fit_rationale": string,',
  '    "anchor_buyer": string,',
  '    "local_wedge": string,',
  '    "existing_players": [string],',
  '    "regulatory_notes": string,',
  '    "alignment_refs": [string]',
  '  },',
  '  "knockout": { "passed": boolean, "reason": string }',
  '}',
  '',
  'alignment_refs must list the exact bracketed source labels (as shown in the evidence block) that support your national_context.',
  'Knockout — set passed=false if ANY of these hold, and name which in reason:',
  '1. Saturated at the national level (multiple established national PRIVATE-SECTOR players already own this space).',
  '2. Regulatory no-go (a hard licensing/regulatory barrier makes it infeasible).',
  '3. No plausible anchor buyer (no sovereign or enterprise entity would credibly buy or fund this — for frontier/deep-tech ideas, this means no sovereign or strategic-capital vehicle with a plausible mandate can be identified even in principle, NOT the absence of a near-term commercial customer).',
  '4. Already implemented by the government (a named authority, council, or platform in the evidence already does substantially the same thing as this idea). Do NOT apply this reason merely because the idea touches a related domain — it must substantially duplicate the named platform\'s core mechanism. An idea that builds a specific, narrow application ON TOP OF an existing platform (rather than replacing it) does not trigger this condition; note that distinction explicitly in fit_rationale instead.',
  'If none hold, passed=true with a brief justification.'
].join('\n');

const userPrompt = [
  'IDEA',
  'Pattern: ' + (abs.pattern || ''),
  'Category: ' + (abs.category || ''),
  'Transferable thesis: ' + (abs.transferable_thesis || ''),
  'Enabling shift: ' + (abs.enabling_shift || ''),
  '',
  'NATIONAL KB EVIDENCE',
  evidenceBlock.trim()
].join('\n');

return [{ json: {
  idea_id: prior.idea_id,
  kb_snapshot_id: snapshotId,
  evidence_refs: evidenceRefs,
  system_prompt: systemPrompt,
  user_prompt: userPrompt
} }];

const out = [];
for (const item of $input.all()) {
  const resp = item.json;
  let content = resp && resp.choices && resp.choices[0] && resp.choices[0].message ? resp.choices[0].message.content : null;
  let parsed = {};
  try { parsed = JSON.parse(content); } catch (e) { parsed = { _parse_error: true, _raw: content }; }
  out.push({ json: {
    idea_id: $('Assemble Context').first().json.idea_id,
    kb_snapshot_id: $('Assemble Context').first().json.kb_snapshot_id,
    evidence_refs: $('Assemble Context').first().json.evidence_refs,
    national_context: parsed.national_context || null,
    knockout: parsed.knockout || null,
    parse_error: parsed._parse_error || false
  } });
}
return out;

const out = [];
for (const item of $input.all()) {
  const resp = item.json;
  const prior = $('Assemble Scoring Context').first().json;
  let content = resp && resp.choices && resp.choices[0] && resp.choices[0].message ? resp.choices[0].message.content : null;
  let parsed = {};
  let parseError = false;
  try { parsed = JSON.parse(content); } catch (e) { parsed = { criteria: [] }; parseError = true; }

  const weightTable = {
    'Strategic alignment with national agenda': 0.20,
    'Economic impact (GDP / jobs / FDI)': 0.15,
    'Feasibility at national level (talent, capital, regulatory readiness)': 0.15,
    'Anchor-demand clarity': 0.15,
    'Differentiation vs. existing national players': 0.10,
    'Defensibility / moat': 0.10,
    'Time to first value': 0.10,
    'Capital efficiency': 0.05
  };

  const criteriaRaw = Array.isArray(parsed.criteria) ? parsed.criteria : [];
  const criteria = [];
  const unmatched = [];
  let weightedScoreSum0to5 = 0;
  let matchedWeightSum = 0;
  let groundedCount = 0;

  for (const c of criteriaRaw) {
    const name = (c && c.name) ? String(c.name).trim() : '';
    const weight = weightTable.hasOwnProperty(name) ? weightTable[name] : null;
    const score = typeof c.score === 'number' ? c.score : parseFloat(c.score);
    const evidenceRef = c.evidence_ref ? String(c.evidence_ref).trim() : 'none';
    const grounded = evidenceRef.toLowerCase() !== 'none' && evidenceRef.trim() !== '';

    if (weight === null) {
      unmatched.push(name);
    } else {
      weightedScoreSum0to5 += (isNaN(score) ? 0 : score) * weight;
      matchedWeightSum += weight;
    }
    if (grounded) groundedCount++;

    criteria.push({ name, score: isNaN(score) ? null : score, weight, evidence_ref: evidenceRef });
  }

  const totalCriteria = criteria.length || 1;
  const groundedShare = groundedCount / totalCriteria;
  let confidenceBand = 'low';
  if (groundedShare >= 0.6) confidenceBand = 'high';
  else if (groundedShare >= 0.3) confidenceBand = 'medium';

  const weightedTotal = Math.round(weightedScoreSum0to5 * 20 * 100) / 100;

  out.push({ json: {
    idea_id: prior.idea_id,
    kb_snapshot_id: prior.kb_snapshot_id,
    national_context: prior.national_context,
    knockout: prior.knockout,
    scoring: {
      criteria,
      weighted_total: weightedTotal,
      confidence_band: confidenceBand,
      grounded_share: Math.round(groundedShare * 1000) / 1000,
      matched_weight_sum: Math.round(matchedWeightSum * 1000) / 1000
    },
    unmatched_criteria: unmatched,
    parse_error: parseError,
    shortlist_eligible: weightedTotal >= 60 && (confidenceBand === 'medium' || confidenceBand === 'high')
  } });
}
return out;

const out = [];
for (const item of $input.all()) {
  const d = item.json;
  out.push({ json: {
    idea_id: d.idea_id,
    kb_snapshot_id: d.kb_snapshot_id,
    national_context: d.national_context,
    scoring: { knockout: d.knockout, criteria: [], weighted_total: null, confidence_band: null }
  } });
}
return out;
